class TestAgentCredentials:
    """Test suite for AgentCredentials class."""

    def test_valid_creation(self, sample_credentials):
        """Test valid credential creation with all fields."""
        assert sample_credentials.agent_id == "agent-001"
        assert "read" in sample_credentials.permissions
        assert sample_credentials.is_valid()

    def test_invalid_agent_id(self):
        """Test rejection of empty or malformed agent IDs."""
        with pytest.raises(ValueError):
            AgentCredentials(agent_id="", public_key="key", permissions=["read"])
        with pytest.raises(ValueError):
            AgentCredentials(agent_id=None, public_key="key", permissions=["read"])

    def test_invalid_public_key(self):
        """Test rejection of empty public keys."""
        with pytest.raises(ValueError):
            AgentCredentials(agent_id="agent-1", public_key="", permissions=["read"])

    def test_invalid_permissions(self):
        """Test rejection of invalid permission sets."""
        with pytest.raises(ValueError):
            AgentCredentials(agent_id="agent-1", public_key="key", permissions=[])
        with pytest.raises(ValueError):
            AgentCredentials(agent_id="agent-1", public_key="key", permissions=["invalid_perm"])

    def test_expired_credentials(self, expired_credentials):
        """Test expired credential detection."""
        assert not expired_credentials.is_valid()
        assert expired_credentials.is_expired()

    def test_future_credentials_valid(self, future_credentials):
        """Test valid future credentials."""
        assert future_credentials.is_valid()
        assert not future_credentials.is_expired()

    def test_permission_checking(self, sample_credentials):
        """Test permission verification."""
        assert sample_credentials.has_permission("read")
        assert sample_credentials.has_permission("execute")
        assert not sample_credentials.has_permission("admin")

    def test_credential_serialization(self, sample_credentials):
        """Test JSON serialization round-trip."""
        serialized = sample_credentials.to_dict()
        restored = AgentCredentials.from_dict(serialized)
        assert restored.agent_id == sample_credentials.agent_id
        assert restored.permissions == sample_credentials.permissions
        assert restored.is_valid()

    def test_credential_hash_integrity(self, sample_credentials):
        """Test credential fingerprint generation."""
        fingerprint = sample_credentials.fingerprint()
        assert isinstance(fingerprint, str)
        assert len(fingerprint) == 64  # SHA-256 hex digest
        # Deterministic
        assert fingerprint == sample_credentials.fingerprint()

    def test_credential_tamper_detection(self, sample_credentials):
        """Test that tampering with credentials invalidates them."""
        original_fingerprint = sample_credentials.fingerprint()
        sample_credentials.permissions.append("admin")
        assert sample_credentials.fingerprint() != original_fingerprint


