class TestSecureMessage:
    """Test suite for SecureMessage class."""

    def test_message_encryption(self, secure_message):
        """Test message encryption produces ciphertext."""
        encrypted = secure_message.encrypt()
        assert encrypted != secure_message.payload
        assert isinstance(encrypted, bytes)

    def test_message_decryption(self, secure_message):
        """Test round-trip encryption/decryption."""
        encrypted = secure_message.encrypt()
        decrypted = secure_message.decrypt(encrypted)
        assert decrypted == secure_message.payload

    def test_message_integrity(self, secure_message):
        """Test HMAC signature verification."""
        encrypted = secure_message.encrypt()
        signature = secure_message.sign(encrypted)
        assert secure_message.verify(encrypted, signature)

    def test_tampered_message_detection(self, secure_message):
        """Test detection of tampered ciphertext."""
        encrypted = bytearray(secure_message.encrypt())
        encrypted[10] ^= 0xFF  # Flip a bit
        with pytest.raises(Exception):
            secure_message.decrypt(bytes(encrypted))

    def test_invalid_key_length(self):
        """Test rejection of invalid encryption key lengths."""
        with pytest.raises(ValueError):
            SecureMessage(
                sender_id="agent-1",
                recipient_id="agent-2",
                payload={"data": "test"},
                encryption_key=b"short-key"  # Invalid length
            )

    def test_empty_payload(self):
        """Test handling of empty payloads."""
        msg = SecureMessage(
            sender_id="agent-1",
            recipient_id="agent-2",
            payload={},
            encryption_key=b"0123456789abcdef0123456789abcdef"
        )
        encrypted = msg.encrypt()
        assert msg.decrypt(encrypted) == {}

    def test_large_payload(self):
        """Test handling of large payloads (1MB)."""
        large_data = {"data": "x" * 1024 * 1024}
        msg = SecureMessage(
            sender_id="agent-1",
            recipient_id="agent-2",
            payload=large_data,
            encryption_key=b"0123456789abcdef0123456789abcdef"
        )
        encrypted = msg.encrypt()
        decrypted = msg.decrypt(encrypted)
        assert decrypted == large_data

    def test_message_metadata(self, secure_message):
        """Test message metadata preservation."""
        assert secure_message.sender_id == "agent-001"
        assert secure_message.recipient_id == "agent-002"
        assert secure_message.timestamp > 0


