class TestSecurityIntegration:
    """End-to-end security workflow tests."""

    def test_full_credential_lifecycle(self, security_manager):
        """Test complete credential lifecycle: create -> use -> rotate -> revoke."""
        # Create credentials
        creds = AgentCredentials(
            agent_id="agent-lifecycle",
            public_key="key-1",
            permissions=["read", "write"]
        )
        security_manager.register_credentials(creds)

        # Use credentials
        token = security_manager.generate_token("agent-lifecycle")
        assert security_manager.validate_token(token, "agent-lifecycle")
        assert security_manager.check_access("agent-lifecycle", "read")

        # Rotate credentials
        new_creds = security_manager.rotate_credentials("agent-lifecycle")
        assert new_creds.public_key != "key-1"

        # Revoke credentials
        security_manager.revoke_credentials("agent-lifecycle")
        assert not security_manager.check_access("agent-lifecycle", "read")

    def test_secure_message_workflow(self, secure_message):
        """Test complete secure messaging workflow."""
        # Encrypt and sign
        encrypted = secure_message.encrypt()
        signature = secure_message.sign(encrypted)

        # Verify and decrypt
        assert secure_message.verify(encrypted, signature)
        decrypted = secure_message.decrypt(encrypted)
        assert decrypted == secure_message.payload

    def test_concurrent_access(self, security_manager):
        """Test concurrent credential access."""
        import threading

        results = []
        def access_agent():
            results.append(security_manager.check_access("agent-001", "read"))

        threads = [threading.Thread(target=access_agent) for _ in range(10)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        assert all(results)  # All should succeed

    def test_security_event_correlation(self, security_manager):
        """Test security event correlation for attack patterns."""
        # Simulate attack pattern
        for i in range(5):
            security_manager.log_security_event(
                f"agent-{i}",
                "failed_login",
                success=False,
                details={"source_ip": "10.0.0.1"}
            )

        # Check for correlated events
        events = security_manager.get_audit_logs()
        failed_events = [e for e in events if e["event"] == "failed_login"]
        assert len(failed_events) == 5
        assert all(e["source_ip"] == "10.0.0.1" for e in failed_events)


