class TestAdversarialScenarios:
    """Security hardening and adversarial input tests."""

    def test_sql_injection_attempt(self, security_manager):
        """Test SQL injection resistance in agent IDs."""
        malicious_id = "'; DROP TABLE credentials; --"
        assert not security_manager.check_access(malicious_id, "read")

    def test_xss_attempt(self, security_manager):
        """Test XSS resistance in log entries."""
        xss_payload = "<script>alert('xss')</script>"
        security_manager.log_security_event("agent-1", xss_payload, success=True)
        logs = security_manager.get_audit_logs()
        assert all(xss_payload not in str(log) for log in logs)

    def test_path_traversal(self, security_manager):
        """Test path traversal resistance."""
        traversal = "../../../etc/passwd"
        assert not security_manager.check_access(traversal, "read")

    def test_unicode_handling(self, security_manager):
        """Test Unicode character handling."""
        unicode_id = "agent-üñïçødé-001"
        creds = AgentCredentials(
            agent_id=unicode_id,
            public_key="key",
            permissions=["read"]
        )
        security_manager.register_credentials(creds)
        assert security_manager.check_access(unicode_id, "read")

    def test_extreme_input_sizes(self, security_manager):
        """Test handling of extreme input sizes."""
        huge_payload = {"data": "x" * 10_000_000}  # 10MB
        msg = SecureMessage(
            sender_id="agent-1",
            recipient_id="agent-2",
            payload=huge_payload,
            encryption_key=b"0123456789abcdef0123456789abcdef"
        )
        encrypted = msg.encrypt()
        assert len(encrypted) > 0

    def test_timing_attack_resistance(self, security_manager):
        """Test timing attack resistance in token validation."""
        import time as time_module

        valid_token = security_manager.generate_token("agent-001")
        invalid_token = "x" * len(valid_token)

        # Measure timing for valid token
        start = time_module.time()
        security_manager.validate_token(valid_token, "agent-001")
        valid_time = time_module.time() - start

        # Measure timing for invalid token
        start = time_module.time()
        security_manager.validate_token(invalid_token, "agent-001")
        invalid_time = time_module.time() - start

        # Timing difference should be minimal
        assert abs(valid_time - invalid_time) < 0.1


